      hlsearch = true;
      incsearch = true;
      mouse = "a";
      mousefocus = true;
      expandtab = true;
      shiftwidth = 4;
      tabstop = 4;
      softtabstop = 4;
      smartindent = true;
      cindent = true;
      smarttab = true;
      scroll = 30;
      shortmess = "c";
      termguicolors = true;
    };

    # Fillchars
    opts.fillchars = {
      vert = "│";
      fold = "⠀";
      eob = " ";
      msgsep = "‾";
      foldopen = "▾";
      foldsep = "│";
      foldclose = "▸";
    };

    # Colorscheme
    colorschemes.catppuccin = {
      enable = true;
      settings = {
        no_italic = true;
      };
    };

    # Keymaps
    keymaps = [
      # Quit
      { key = "<C-q>"; action = ":q<CR>"; }
      # Copy all text
      { key = "<C-a>"; action = "%y+<CR>"; }
      # Save
      { mode = "i"; key = "<C-s>"; action = ":w<CR>"; }
      { mode = "n"; key = "<C-s>"; action = ":w<CR>"; }
      # NvimTree
      { key = "<leader>t"; action = ":NvimTreeToggle<CR>"; }
      { key = "<leader>tf"; action = ":NvimTreeFocus<CR>"; }
      # Type ignore
      { key = "<leader>h"; action = ":Tyig<CR>"; }
      # BufferLine
      { key = "<Tab>"; action = ":BufferLineCycleNext<CR>"; }
      { key = "<leader><Tab>"; action = ":BufferLineCyclePrev<CR>"; }
      { key = "<C-H>"; action = ":BufferLineCloseOthers<CR>"; }
      { key = "<leader><Esc>"; action = ":bd<CR>"; }
      # TodoList
      { key = "<leader>nl"; action = ":TodoTelescope<CR>"; }
      # ToggleTerm
      { key = "<leader>s"; action = ":ToggleTerm direction=float<CR>"; }
      # Telescope
      { key = "<leader>ff"; action = "<cmd>Telescope find_files<CR>"; }
      { key = "<leader>ft"; action = "<cmd>Telescope live_grep<CR>"; }
      { key = "<leader>fb"; action = "<cmd>Telescope buffers<CR>"; }
      { key = "<leader>fh"; action = "<cmd>Telescope help_tags<CR>"; }
      # Git
      { key = "<leader>gb"; action = "<cmd>Telescope git_branches<CR>"; }
      { key = "<leader>gc"; action = "<cmd>Telescope git_commits<CR>"; }
      { key = "<leader>gs"; action = "<cmd>Telescope git_status<CR>"; }
      # Colorscheme
      { key = "<leader>cs"; action = "<cmd>Telescope colorscheme<CR>"; }
      # LSP diagnostics
      { key = "<space>e"; action = "<cmd>lua vim.diagnostic.open_float()<CR>"; }
      { key = "<C-[>"; action = "<cmd>lua vim.diagnostic.goto_prev()<CR>"; }
      { key = "<C-]>"; action = "<cmd>lua vim.diagnostic.goto_next()<CR>"; }
      # LSP actions (buffer-local, set via LspAttach)
      { mode = "n"; key = "<C-d>"; action = "<cmd>lua vim.lsp.buf.declaration()<CR>"; }
      { mode = "n"; key = "<C-l>"; action = "<cmd>lua vim.lsp.buf.definition()<CR>"; }
      { mode = "n"; key = "<C-f>"; action = "<cmd>lua vim.lsp.buf.hover()<CR>"; }
      { mode = "n"; key = "i"; action = "<cmd>lua vim.lsp.buf.implementation()<CR>"; }
      { mode = "n"; key = "<C-r>"; action = "<cmd>lua vim.lsp.buf.signature_help()<CR>"; }
      { mode = "n"; key = "<space>r"; action = "<cmd>lua vim.lsp.buf.code_action()<CR>"; }
      { mode = "n"; key = "gr"; action = "<cmd>lua vim.lsp.buf.references()<CR>"; }
      { mode = "n"; key = "<space>f"; action = "<cmd>lua vim.lsp.buf.format({async=true})<CR>"; }
      # Terminal keymaps
      { mode = "t"; key = "<esc>"; action = "<C-\\><C-n>"; }
      { mode = "t"; key = "jk"; action = "<C-\\><C-n>"; }
    ];

    # Plugins
    plugins = {
      # Treesitter
      treesitter = {
        enable = true;
        settings = {
          ensure_installed = [
            "bash" "css" "dockerfile" "html" "javascript" "json" "json5"
            "lua" "python" "vim" "yaml" "c" "go" "rust" "nix"
          ];
          highlight.enable = true;
          auto_install = true;
        };
      };

      # LSP
      lsp = {
        enable = true;
        servers = {
          nixd.enable = true;
          pyright.enable = true;
          ruff.enable = true;
          ts_ls.enable = true;
          gopls.enable = true;
          rust_analyzer.enable = true;
          bashls.enable = true;
          cssls.enable = true;
          html.enable = true;
          jsonls.enable = true;
          yamlls.enable = true;
          dockerls.enable = true;
          lua_ls.enable = true;
          emmet_ls.enable = true;
        };
        keymaps = {
          diagnostic_goto_prev = "<C-[>";
          diagnostic_goto_next = "<C-]>";
        };
      };

      # Mason
      mason = {
        enable = true;
        settings = {
          ui = {
            icons = {
              package_installed = "✓";
              package_pending = "➜";
              package_uninstalled = "✗";
            };
          };
        };
      };

      mason-lspconfig.enable = true;

      # CMP (autocomplete)
      cmp = {
        enable = true;
        settings = {
          snippet.expand = "function(args) require('luasnip').lsp_expand(args.body) end";
          window = {
            completion = lib.nixvim.mkRaw "cmp.config.window.bordered()";
